export { default as AISidebar } from "./src/AISidebar.vue";
export * from "./src/tree";

export type * from "./src/api-types";

// Vue public prop types, derived from the actual components.
export type AISidebarProps = InstanceType<
  (typeof import("./AISidebar.vue"))["default"]
>["$props"];

export type SidebarResourceKind = "folder" | "project" | "file" | "bookmark";
export interface SidebarResource {
  id: string;
  label: string;
  kind: SidebarResourceKind;
  children?: SidebarResource[];
  disabled?: boolean;
}
export type SidebarResourceDropPosition = "before" | "inside" | "after";
export interface SidebarResourceMove {
  itemId: string;
  targetId: string | null;
  position: SidebarResourceDropPosition;
}
export interface SidebarResourceMoveCommands {
  up?: () => void;
  down?: () => void;
  into?: { label: string; run: () => void };
  out?: () => void;
}
export interface SidebarResourceMenuControls {
  close: () => void;
  rename: () => void;
  moves: SidebarResourceMoveCommands;
}
export interface FlatResource {
  item: SidebarResource;
  depth: number;
  parentId: string | null;
}

export function canContain(item: SidebarResource) {
  return ["folder", "project"].includes(item.kind);
}

function pathTo(forest: SidebarResource[], id: string): number[] | undefined {
  const pending = forest
    .map((item, index) => ({ item, path: [index] }))
    .reverse();
  while (pending.length) {
    const cursor = pending.pop()!;
    if (cursor.item.id === id) return cursor.path;
    const children = cursor.item.children ?? [];
    for (let index = children.length - 1; index >= 0; index--)
      pending.push({ item: children[index], path: [...cursor.path, index] });
  }
}
function at(forest: SidebarResource[], path: number[]): SidebarResource {
  let nodes = forest;
  let node = nodes[path[0]];
  path.forEach((index, level) => {
    node = nodes[index];
    if (level < path.length - 1) nodes = node.children ?? [];
  });
  return node;
}
function editSiblings(
  forest: SidebarResource[],
  parentPath: number[],
  edit: (siblings: SidebarResource[]) => SidebarResource[],
): SidebarResource[] {
  if (!parentPath.length) return edit(forest);
  const [head, ...tail] = parentPath;
  const result = forest.slice();
  result[head] = {
    ...forest[head],
    children: editSiblings(forest[head].children ?? [], tail, edit),
  };
  return result;
}
export function flattenResources(
  items: SidebarResource[],
  expanded: Set<string>,
  depth = 0,
  parentId: string | null = null,
): FlatResource[] {
  const result: FlatResource[] = [];
  const pending = items.map((item) => ({ item, depth, parentId })).reverse();
  while (pending.length) {
    const row = pending.pop()!;
    result.push(row);
    if (!expanded.has(row.item.id)) continue;
    const children = row.item.children ?? [];
    for (let index = children.length - 1; index >= 0; index--)
      pending.push({
        item: children[index],
        parentId: row.item.id,
        depth: row.depth + 1,
      });
  }
  return result;
}
export function findResource(
  items: SidebarResource[],
  id: string,
): SidebarResource | undefined {
  const path = pathTo(items, id);
  return path ? at(items, path) : undefined;
}
export function containsResource(item: SidebarResource, id: string): boolean {
  return pathTo([item], id) !== undefined;
}
export function removeResource(
  items: SidebarResource[],
  id: string,
): { items: SidebarResource[]; removed?: SidebarResource } {
  const path = pathTo(items, id);
  if (!path) return { items: items.slice() };
  const removed = at(items, path);
  const index = path[path.length - 1];
  return {
    removed,
    items: editSiblings(items, path.slice(0, -1), (siblings) =>
      siblings.filter((_, cursor) => cursor !== index),
    ),
  };
}
export function insertResource(
  items: SidebarResource[],
  resource: SidebarResource,
  targetId: string | null,
  position: SidebarResourceDropPosition,
): SidebarResource[] {
  if (targetId === null) return items.concat(resource);
  const path = pathTo(items, targetId);
  if (!path) return items.slice();
  if (position === "inside")
    return editSiblings(items, path, (children) => children.concat(resource));
  const index = path[path.length - 1] + Number(position === "after");
  return editSiblings(items, path.slice(0, -1), (siblings) => [
    ...siblings.slice(0, index),
    resource,
    ...siblings.slice(index),
  ]);
}
export function moveResource(
  items: SidebarResource[],
  move: SidebarResourceMove,
): SidebarResource[] | null {
  const source = findResource(items, move.itemId);
  if (!source || source.disabled) return null;
  const target =
    move.targetId === null ? undefined : findResource(items, move.targetId);
  if (
    move.targetId !== null &&
    (!target || containsResource(source, move.targetId))
  )
    return null;
  if (
    move.position === "inside" &&
    (!target || target.disabled || !canContain(target))
  )
    return null;
  const detached = removeResource(items, move.itemId);
  return insertResource(detached.items, source, move.targetId, move.position);
}
export function renameResource(
  items: SidebarResource[],
  id: string,
  label: string,
): SidebarResource[] {
  const path = pathTo(items, id);
  if (!path) return items.slice();
  const index = path[path.length - 1];
  return editSiblings(items, path.slice(0, -1), (siblings) =>
    siblings.map((item, cursor) =>
      cursor === index ? { ...item, label } : item,
    ),
  );
}

import { onBeforeUnmount, onMounted, ref } from "vue";
export function useTouchCapable() {
  const capable = ref(false);
  let media: MediaQueryList | undefined;
  const refresh = () => {
    capable.value = !!media?.matches || navigator.maxTouchPoints > 0;
  };
  onMounted(() => {
    media = window.matchMedia?.("(any-pointer: coarse)");
    refresh();
    media?.addEventListener?.("change", refresh);
  });
  onBeforeUnmount(() => media?.removeEventListener?.("change", refresh));
  return capable;
}

export {
  RenderNode,
  useControllable,
  useOutside,
  useReduced,
  rove,
  type Content,
} from "../blocks/shared";
import { onBeforeUnmount, ref } from "vue";

export function useClipboard(
  read: () => string,
  callback?: () => void | Promise<void>,
) {
  const copied = ref(false);
  let reset: ReturnType<typeof setTimeout> | undefined;
  let generation = 0;
  let alive = true;
  async function copy() {
    const request = ++generation;
    if (reset !== undefined) clearTimeout(reset);
    copied.value = false;
    try {
      if (callback) await callback();
      else await navigator.clipboard.writeText(read());
      if (!alive || request !== generation) return;
      copied.value = true;
      reset = setTimeout(() => {
        if (alive) copied.value = false;
      }, 1600);
    } catch {
      if (alive && request === generation) copied.value = false;
    }
  }
  onBeforeUnmount(() => {
    alive = false;
    generation++;
    if (reset !== undefined) clearTimeout(reset);
  });
  return { copied, copy };
}

import { onMounted, onUnmounted, watch, type Ref } from "vue";
import { resolveElement, useFloatingLayer } from "../lib/composables";

type HitTest = (target: Element) => boolean;
const openScopes = new Set<HitTest>();

export function useBlockDismiss(
  open: Ref<boolean>,
  root: Ref<unknown>,
  close: () => void,
  consume = false,
) {
  const layer = useFloatingLayer(open, root);
  const pendingClicks = new Set<() => void>();
  let stopWatching: (() => void) | undefined;
  function interceptActivation(source: Event) {
    const release = () => {
      window.removeEventListener("click", click, true);
      window.removeEventListener("pointerdown", replacement, true);
      window.removeEventListener("pointercancel", replacement, true);
      window.removeEventListener("keydown", release, true);
      pendingClicks.delete(release);
    };
    function click(event: MouseEvent) {
      event.preventDefault();
      event.stopPropagation();
      release();
    }
    function replacement(event: Event) {
      if (event !== source) release();
    }
    pendingClicks.add(release);
    window.addEventListener("click", click, true);
    window.addEventListener("pointerdown", replacement, true);
    window.addEventListener("pointercancel", replacement, true);
    window.addEventListener("keydown", release, true);
  }
  onMounted(() => {
    stopWatching = watch(
      open,
      (visible, _, cleanup) => {
        if (!visible) return;
        const contains: HitTest = (target) =>
          resolveElement<HTMLElement>(root.value)?.contains(target) ?? false;
        const keydown = (event: KeyboardEvent) => {
          if (layer.claimEscape(event)) close();
        };
        const pointerdown = (event: PointerEvent) => {
          const target = event.target;
          if (
            !(target instanceof Element) ||
            contains(target) ||
            layer.containsHigher(target)
          )
            return;
          let anotherScope = false;
          if (consume)
            for (const hit of openScopes)
              if (hit !== contains && hit(target)) {
                anotherScope = true;
                break;
              }
          if (consume && !anotherScope) interceptActivation(event);
          close();
        };
        openScopes.add(contains);
        window.addEventListener("keydown", keydown);
        window.addEventListener("pointerdown", pointerdown, true);
        cleanup(() => {
          openScopes.delete(contains);
          window.removeEventListener("keydown", keydown);
          window.removeEventListener("pointerdown", pointerdown, true);
        });
      },
      { immediate: true },
    );
  });
  onUnmounted(() => {
    stopWatching?.();
    for (const release of pendingClicks) release();
  });
  return layer;
}

import { useBlockDismiss } from "./dismiss";
import { resolveElement, useOverlay } from "../lib/composables";
import {
  computed,
  defineComponent,
  h,
  isVNode,
  onMounted,
  onUnmounted,
  ref,
  type Component,
  type Ref,
  type VNodeChild,
} from "vue";

export type Content = VNodeChild | Component;
export const RenderNode = defineComponent({
  props: ["node"],
  setup(props) {
    return () => {
      const node = props.node;
      if (isVNode(node) || node === null || node === undefined) return node;
      if (typeof node === "function" || typeof node === "object")
        return h(node as Component);
      return node;
    };
  },
});

export function useControllable<T>(
  get: () => T | undefined,
  initial: T,
  emit: (value: T) => void,
) {
  const saved = ref(initial) as Ref<T>;
  return computed<T>({
    get() {
      const value = get();
      return value === undefined ? saved.value : value;
    },
    set(value) {
      if (get() === undefined) saved.value = value;
      emit(value);
    },
  });
}

export function useOutside(
  root: Ref<HTMLElement | undefined>,
  close: () => void,
  open: Ref<boolean>,
) {
  useBlockDismiss(open, root, close);
}

export function useReduced() {
  const reduced = ref(false);
  let detach: (() => void) | undefined;
  onMounted(() => {
    if (typeof matchMedia !== "function") return;
    const query = matchMedia("(prefers-reduced-motion: reduce)");
    const read = () => {
      reduced.value = query.matches;
    };
    read();
    query.addEventListener("change", read);
    detach = () => query.removeEventListener("change", read);
  });
  onUnmounted(() => detach?.());
  return reduced;
}

export function rove(
  event: KeyboardEvent,
  root: HTMLElement,
  selector = "button:not(:disabled)",
) {
  const items = [...root.querySelectorAll<HTMLElement>(selector)];
  if (!items.length) return;
  const current = items.indexOf(
    root.ownerDocument.activeElement as HTMLElement,
  );
  let destination: number;
  switch (event.key) {
    case "ArrowRight":
    case "ArrowDown":
      destination = (current + 1) % items.length;
      break;
    case "ArrowLeft":
    case "ArrowUp":
      destination = (current - 1 + items.length) % items.length;
      break;
    case "Home":
      destination = 0;
      break;
    case "End":
      destination = items.length - 1;
      break;
    default:
      return;
  }
  event.preventDefault();
  items[destination]?.focus();
}

export function useDialog(
  open: Ref<boolean>,
  root: Ref<HTMLElement | undefined>,
  initial?: () => HTMLElement | undefined,
) {
  const element = computed(() => resolveElement<HTMLElement>(root.value));
  useOverlay(
    open,
    element,
    () => {
      open.value = false;
    },
    initial,
  );
}

import { computed, getCurrentInstance, nextTick, onBeforeUnmount, onMounted, ref, watch, type Ref } from "vue";
import { layerManager, type Layer } from "./layers";

export function useControllable<T>(props: Record<string, any>, key: string, emit: (...args: any[]) => void, fallback: T) {
  const local = ref<T>(fallback) as Ref<T>;
  const read = () => props[key] as T | undefined;
  return computed<T>({
    get() { const supplied = read(); return supplied === undefined ? local.value : supplied; },
    set(value) { if (read() === undefined) local.value = value; emit(`update:${key}`, value); },
  });
}

export function useMediaQuery(query: string) {
  const matches = ref(false);
  let disconnect: (() => void) | undefined;
  onMounted(() => {
    if (typeof window.matchMedia !== "function") return;
    const media = window.matchMedia(query);
    const update = () => { matches.value = media.matches; };
    update();
    media.addEventListener?.("change", update);
    disconnect = () => media.removeEventListener?.("change", update);
  });
  onBeforeUnmount(() => disconnect?.());
  return matches;
}
export function useReducedMotion() { return useMediaQuery("(prefers-reduced-motion: reduce)"); }

const lockedProperties = ["overflow", "position", "top", "left", "right", "width"] as const;
let scrollOwners = 0;
let unlockPage: (() => void) | undefined;
function acquirePage() {
  if (scrollOwners++ === 0) {
    const body = document.body.style;
    const saved = lockedProperties.map(name => ({ name, value: body.getPropertyValue(name), priority: body.getPropertyPriority(name) }));
    const x = window.scrollX, y = window.scrollY;
    body.setProperty("overflow", "hidden");
    body.setProperty("position", "fixed");
    body.setProperty("left", `${-x}px`);
    body.setProperty("top", `${-y}px`);
    body.setProperty("right", "0px");
    body.setProperty("width", "100%");
    unlockPage = () => {
      for (const entry of saved) {
        if (entry.value) body.setProperty(entry.name, entry.value, entry.priority);
        else body.removeProperty(entry.name);
      }
      const root = document.documentElement.style;
      const behavior = root.getPropertyValue("scroll-behavior");
      const priority = root.getPropertyPriority("scroll-behavior");
      root.setProperty("scroll-behavior", "auto");
      window.scrollTo(x, y);
      if (behavior) root.setProperty("scroll-behavior", behavior, priority);
      else root.removeProperty("scroll-behavior");
    };
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--scrollOwners === 0) { unlockPage?.(); unlockPage = undefined; }
  };
}
export function useScrollLock(locked: Ref<boolean>) {
  let mounted = false;
  let release: (() => void) | undefined;
  const update = (value: boolean) => {
    if (!mounted) return;
    if (value && !release) release = acquirePage();
    if (!value && release) { release(); release = undefined; }
  };
  onMounted(() => { mounted = true; update(locked.value); });
  watch(locked, update);
  onBeforeUnmount(() => { release?.(); release = undefined; mounted = false; });
}

export function resolveElement<T extends Element = HTMLElement>(value: unknown): T | null {
  if (!value) return null;
  const unwrapped = (value as { $el?: unknown }).$el ?? value;
  return typeof (unwrapped as Element).nodeType === "number" && (unwrapped as Element).nodeType === 1 ? unwrapped as T : null;
}
const focusable = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function createLayer(modal: boolean, panel?: { readonly value: unknown }): Layer {
  return { key: Symbol("orvui-layer"), modal, owner: getCurrentInstance(), surface: () => resolveElement(panel?.value), returnTo: null };
}
export function useOverlay(open: Ref<boolean>, panel: Ref<HTMLElement | null>, close: () => void, initialFocus?: () => HTMLElement | undefined) {
  const layer = createLayer(true, panel);
  let mounted = false;
  let revision = 0;
  const sync = async (value: boolean) => {
    const current = ++revision;
    if (!mounted) return;
    if (!value) { layerManager.detach(layer, true); return; }
    if (!layerManager.attach(layer)) return;
    await nextTick();
    if (!mounted || current !== revision || !open.value || !layerManager.top(layer)) return;
    (initialFocus?.() ?? layer.surface()?.querySelector<HTMLElement>(focusable) ?? layer.surface())?.focus({ preventScroll: true });
  };
  const onKey = (event: KeyboardEvent) => {
    if (event.defaultPrevented || !open.value) return;
    if (event.key === "Escape" && layerManager.top(layer)) {
      event.preventDefault(); event.stopPropagation(); close(); return;
    }
    if (event.key !== "Tab" || !layerManager.modal(layer)) return;
    const candidates = new Set<HTMLElement>();
    for (const surface of layerManager.scopes(layer)) {
      for (const node of surface.querySelectorAll<HTMLElement>(focusable)) {
        if (node.getClientRects().length > 0 && !node.closest("[inert]")) candidates.add(node);
      }
    }
    event.preventDefault();
    const nodes = [...candidates];
    if (!nodes.length) { layer.surface()?.focus(); return; }
    const position = nodes.indexOf(document.activeElement as HTMLElement);
    const next = position < 0 ? (event.shiftKey ? nodes.length - 1 : 0) : (position + (event.shiftKey ? -1 : 1) + nodes.length) % nodes.length;
    nodes[next].focus();
  };
  useScrollLock(open);
  onMounted(() => { mounted = true; document.addEventListener("keydown", onKey); void sync(open.value); });
  watch(open, value => void sync(value));
  onBeforeUnmount(() => { mounted = false; revision++; document.removeEventListener("keydown", onKey); layerManager.detach(layer, true); });
  return {
    isTop: () => open.value && layerManager.top(layer),
    containsHigher: (target: EventTarget | null) => layerManager.higher(layer, target),
    containsOwnedPortal: (target: HTMLElement) => layerManager.containsPortal(layer.owner, target),
  };
}
export function useFloatingLayer(open: Ref<boolean>, panel?: { readonly value: unknown }) {
  const layer = createLayer(false, panel);
  let mounted = false;
  let unregister: (() => void) | undefined;
  const sync = (value: boolean) => {
    if (!mounted) return;
    if (value) layerManager.attach(layer); else layerManager.detach(layer, false);
  };
  onMounted(() => { mounted = true; unregister = layerManager.portal(layer.owner, layer.surface); sync(open.value); });
  watch(open, sync, { flush: "sync" });
  onBeforeUnmount(() => { mounted = false; unregister?.(); layerManager.detach(layer, false); });
  const isTop = () => open.value && layerManager.top(layer);
  return {
    isTop,
    claimEscape(event: KeyboardEvent) {
      if (event.key !== "Escape" || event.defaultPrevented || !isTop()) return false;
      event.preventDefault(); event.stopImmediatePropagation(); return true;
    },
    containsHigher: (target: EventTarget | null) => layerManager.higher(layer, target),
  };
}
export function useEventListener(target: () => EventTarget | null | undefined, event: string, handler: EventListener, options?: AddEventListenerOptions) {
  let remove: (() => void) | undefined;
  onMounted(() => { const element = target(); element?.addEventListener(event, handler, options); remove = () => element?.removeEventListener(event, handler, options); });
  onBeforeUnmount(() => remove?.());
}

export const EASE_OUT = [0.16, 1, 0.3, 1] as const;
export const EASE_IN_OUT = [0.77, 0, 0.175, 1] as const;
export const EASE_DRAWER = [0.32, 0.72, 0, 1] as const;
export const EASE_OUT_CSS = "cubic-bezier(0.16,1,0.3,1)";
export const SPRING_PRESS = {
  type: "spring",
  stiffness: 500,
  damping: 30,
  mass: 0.6,
} as const;
export const SPRING_SWAP = {
  type: "spring",
  stiffness: 460,
  damping: 30,
  mass: 0.55,
} as const;
export const SPRING_PANEL = {
  type: "spring",
  stiffness: 420,
  damping: 40,
  mass: 0.5,
} as const;
export const SPRING_LAYOUT = {
  type: "spring",
  stiffness: 360,
  damping: 32,
  mass: 0.6,
} as const;
export const SPRING_MOUSE = { stiffness: 200, damping: 15, mass: 0.3 } as const;
export const SPRING_GLIDE = { stiffness: 700, damping: 50, mass: 0.5 } as const;
export const SPRING_TIMELINE = {
  type: "spring",
  stiffness: 120,
  damping: 24,
  mass: 1,
} as const;

import type { ComponentInternalInstance } from "vue";

type Surface = () => HTMLElement | null;
export interface Layer {
  key: symbol;
  modal: boolean;
  owner: ComponentInternalInstance | null;
  surface: Surface;
  returnTo: HTMLElement | null;
}
const active: Layer[] = [];
const portals = new Set<{ owner: ComponentInternalInstance | null; surface: Surface }>();

function belongsTo(child: ComponentInternalInstance | null, parent: ComponentInternalInstance | null) {
  if (!parent) return false;
  for (let node = child; node; node = node.parent) if (node === parent) return true;
  return false;
}
function later(layer: Layer) {
  const index = active.indexOf(layer);
  return index < 0 ? [] : active.slice(index + 1);
}
export const layerManager = {
  attach(layer: Layer) {
    if (active.includes(layer)) return false;
    layer.returnTo = document.activeElement as HTMLElement | null;
    const before = active.findIndex(entry => entry.owner !== layer.owner && belongsTo(entry.owner, layer.owner));
    active.splice(before < 0 ? active.length : before, 0, layer);
    return true;
  },
  detach(layer: Layer, restore: boolean) {
    const index = active.indexOf(layer);
    if (index < 0) return;
    const wasLast = index === active.length - 1;
    const surface = layer.surface();
    for (const successor of later(layer)) {
      if (successor.returnTo && surface?.contains(successor.returnTo)) successor.returnTo = layer.returnTo;
    }
    active.splice(index, 1);
    if (restore && wasLast && layer.returnTo?.isConnected) layer.returnTo.focus({ preventScroll: true });
  },
  top(layer: Layer) { return active.at(-1) === layer; },
  modal(layer: Layer) { return active.slice().reverse().find(entry => entry.modal) === layer; },
  higher(layer: Layer, target: EventTarget | null) {
    return !!target && typeof (target as Node).nodeType === "number" && later(layer).some(entry => entry.surface()?.contains(target as Node));
  },
  scopes(layer: Layer) {
    const result = [layer.surface()];
    for (const entry of later(layer)) if (!entry.modal && belongsTo(entry.owner, layer.owner)) result.push(entry.surface());
    return result.filter((surface): surface is HTMLElement => surface !== null);
  },
  portal(owner: ComponentInternalInstance | null, surface: Surface) {
    const portal = { owner, surface };
    portals.add(portal);
    return () => portals.delete(portal);
  },
  containsPortal(owner: ComponentInternalInstance | null, target: HTMLElement) {
    for (const portal of portals) {
      const node = portal.surface();
      if (node && belongsTo(portal.owner, owner) && target.contains(node)) return true;
    }
    return false;
  },
};

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: unknown[]) {
  const combined = clsx(...inputs as ClassValue[]);
  return twMerge(combined);
}
export function clamp(value: number, min: number, max: number) {
  const aboveFloor = Math.max(min, value);
  return Math.min(aboveFloor, max);
}

export { default as Popover } from "./src/Popover.vue";
export { default as PopoverTrigger } from "./src/PopoverTrigger.vue";
export { default as PopoverContent } from "./src/PopoverContent.vue";
export { default as MorphPopover } from "./src/MorphPopover.vue";
export { default as MorphPopoverContent } from "./src/MorphPopoverContent.vue";
export { default as MorphPopoverTrigger } from "./src/MorphPopoverTrigger.vue";

export type * from "./src/api-types";

// Vue public prop types, derived from the actual components.
export type MorphPopoverContentProps = InstanceType<
  (typeof import("./MorphPopoverContent.vue"))["default"]
>["$props"];
export type MorphPopoverProps = InstanceType<
  (typeof import("./MorphPopover.vue"))["default"]
